function AdminAsset({ src, alt }: { src: string; alt: string }) {
  const isLogo = src.endsWith("/xiongzai-logo.png");
  // Vinext does not provide the next/image runtime; these are fixed, same-origin assets with explicit intrinsic sizes.
  // eslint-disable-next-line @next/next/no-img-element
  return <img src={src} alt={alt} width={isLogo ? 1448 : 190} height={isLogo ? 1086 : 190} decoding="async" loading="eager" />;
}

