const ListSortContext = createContext<{ sort: CreatedSort; setSort: (value: string) => void }>({ sort: "created_desc", setSort: () => undefined });

function hasPermission(permissions: Set<string>, keys: string[]) { return keys.some((key) => permissions.has(key)); }
function asRecord(value: unknown): ApiRecord { return value && typeof value === "object" ? value as ApiRecord : {}; }
function recordOf(value: unknown): ApiRecord { return value as unknown as ApiRecord; }
function arrayPayload<T>(value: unknown): T[] { if (Array.isArray(value)) return value as T[]; const record = asRecord(value); return Array.isArray(record.items) ? record.items as T[] : []; }
function cents(value: string | number | bigint | null | undefined) { try { const amount = BigInt(value ?? 0); return `¥ ${(amount / 100n).toString()}.${(amount % 100n).toString().padStart(2, "0")}`; } catch { return "—"; } }
function time(value: string | null | undefined) { if (!value) return "—"; const date = new Date(value); return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString("zh-CN", { hour12: false }); }
function statusLabel(value: string | null | undefined) { return value ? STATUS_LABELS[value] ?? `未知状态（${value}）` : "—"; }
const FIELD_TOKEN_LABELS:Record<string,string>={current:"当前",public:"公开",profile:"资料",application:"申请",review:"审核",log:"记录",history:"历史",availability:"可接单",slot:"时段",file:"文件",image:"图片",voice:"声音",avatar:"头像",cover:"封面",seller:"陪玩",product:"服务",service:"服务",order:"订单",payment:"支付",refund:"退款",complaint:"投诉",support:"客服",policy:"协议",acceptance:"接受",notification:"通知",delivery:"投递",phone:"手机号",change:"换绑",export:"导出",job:"任务",account:"账号",cancellation:"注销",identity:"实名",verification:"认证",provider:"渠道",transaction:"流水",request:"请求",trace:"追踪",error:"错误",attempt:"尝试",count:"数量",duration:"时长",reason:"原因",status:"状态",type:"类型",name:"名称",title:"标题",description:"说明",content:"内容",amount:"金额",price:"价格",fee:"费用",income:"收入",number:"编号",no:"编号",time:"时间",date:"日期",at:"时间",from:"开始",to:"结束",old:"原",new:"新",masked:"脱敏",mask:"脱敏",mode:"模式",version:"版本",value:"值",action:"操作",user:"用户",admin:"管理员",created:"创建",updated:"更新",submitted:"提交",reviewed:"审核",approved:"通过",rejected:"驳回",completed:"完成",cancelled:"取消",started:"开始",finished:"结束",expires:"过期",read:"阅读",sent:"发送",related:"关联",required:"需要",fields:"字段",snapshot:"快照",logs:"记录",applications:"申请记录",slots:"时段",policies:"协议"};
function fieldLabel(key:string){if(FIELD_LABELS[key])return FIELD_LABELS[key];const tokens=key.toLowerCase().split("_").filter(Boolean);if(tokens.length&&tokens.every((token)=>FIELD_TOKEN_LABELS[token]))return tokens.map((token)=>FIELD_TOKEN_LABELS[token]).join("");return "其他业务信息";}
function fieldValueLabel(key:string,value:unknown){if(value===null||value===undefined||value==="")return "—";if(typeof value==="boolean")return value?"是":"否";if(/(?:_amount|_price|_fee|_income|_gmv|_cent)$/u.test(key))return cents(value as string|number|bigint);if(/(?:_at|_time)$/u.test(key)&&typeof value==="string")return time(value);if(typeof value==="string"&&(key==="status"||key.endsWith("_status")))return statusLabel(value);if(typeof value==="string"&&VALUE_LABELS[value])return VALUE_LABELS[value];if(key==="notification_type")return "业务通知";if(key==="category")return "业务消息";if(key==="provider")return "本地测试渠道";if(typeof value==="string"&&/^[A-Z][A-Z0-9_]+$/u.test(value))return `未识别类型（${value}）`;return safeText(value);}
function safeText(value: unknown): string { if (value === null || value === undefined || value === "") return "—"; if (typeof value === "object") return JSON.stringify(value); return String(value); }
function sanitizeRecord(value: unknown, depth = 0): unknown {
  if (depth > 8) return "[内容层级过深]";
  if (Array.isArray(value)) return value.map((item) => sanitizeRecord(item, depth + 1));
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(Object.entries(value as ApiRecord).filter(([key]) => !SENSITIVE_KEY.test(key)).map(([key, item]) => [key, sanitizeRecord(item, depth + 1)]));
}

function StatusBadge({ value }: { value: string }) {
  const danger = /REJECT|DISABLED|FAILED|CLOSED|HIDDEN|OFF_SALE|URGENT/iu.test(value);
  const warning = /PENDING|SUBMITTED|REVIEW|WAITING|OPEN|TRANSFERRED|CREATED/iu.test(value);
  return <span className={`${styles.statusBadge} ${danger ? styles.badgeDanger : warning ? styles.badgeWarning : styles.badgeSuccess}`}>{statusLabel(value)}</span>;
}

function CancellationStatusBadge({ value }: { value: AccountCancellation["status"] }) {
  const labels: Record<AccountCancellation["status"], string> = { REQUESTED: "待处理", CANCELLED: "用户已撤销", PROCESSING: "处理中", COMPLETED: "注销完成", REJECTED: "管理员已拒绝" };
  const danger = value === "REJECTED"; const warning = value === "REQUESTED" || value === "PROCESSING";
  return <span className={`${styles.statusBadge} ${danger ? styles.badgeDanger : warning ? styles.badgeWarning : styles.badgeSuccess}`}>{labels[value]}</span>;
}

