function DataStateView({ state, failure, onRetry, emptyTitle = "暂无真实业务数据", emptyNote = "接口已正常返回，当前没有符合条件的记录。" }: { state: DataState; failure?: Failure | null; onRetry?: () => void; emptyTitle?: string; emptyNote?: string }) {
  const view = state === "loading" ? ["", "正在读取真实数据", "请稍候"] : state === "offline" ? ["!", "网络连接已断开", failure?.message ?? "恢复网络后重试"] : state === "error" ? ["!", "数据读取失败", failure?.message ?? "请稍后重试"] : ["∅", emptyTitle, emptyNote];
  return <section className={styles.dataState} role={state === "error" || state === "offline" ? "alert" : "status"}>
    <span className={state === "loading" ? styles.stateLoading : undefined}>{view[0]}</span><h2>{view[1]}</h2><p>{view[2]}</p>
    {failure?.requestId ? <p>请求编号：{failure.requestId}</p> : null}{onRetry && state !== "loading" ? <button onClick={onRetry}>重新加载</button> : null}
  </section>;
}

